#!/usr/bin/php
<?php

/**
 * Validation script for the ansiToHtml() and ansiToText() methods of \Temma\Utils\Text.
 * Uses the sequences generated by \Temma\Utils\Ansi and \Temma\Utils\Term, and hand-written sequences.
 */

require_once(__DIR__ . '/../lib/Temma/Base/Autoload.php');

use \Temma\Utils\Ansi as TµAnsi;
use \Temma\Utils\Text as TµText;

\Temma\Base\Autoload::autoload(__DIR__ . '/../lib');

/* ********** TEST MICRO-FRAMEWORK ********** */
$count = 0;
$failed = 0;
/**
 * Checks that a value is equal to the expected one.
 * @param	string	$label		Test label.
 * @param	mixed	$result		Obtained value.
 * @param	mixed	$expected	Expected value.
 */
function check(string $label, mixed $result, mixed $expected) : void {
	global $count, $failed;
	$count++;
	$ok = ($result === $expected);
	if (!$ok)
		$failed++;
	print(TµAnsi::faint(sprintf('%02d', $count)) . ' ' .
	      TµAnsi::color(($ok ? 'green' : 'red'), ($ok ? 'OK' : 'KO')) . " $label\n");
	if (!$ok) {
		print('   expected: ' . var_export($expected, true) . "\n");
		print('   obtained: ' . var_export($result, true) . "\n");
	}
}

/* ********** ansiToText() ********** */
print(TµAnsi::bold("ansiToText()\n"));
check("null and empty string", [TµText::ansiToText(null), TµText::ansiToText('')], ['', '']);
check("text without sequence", TµText::ansiToText("a < b\nc"), "a < b\nc");
check("Ansi styles", TµText::ansiToText(TµAnsi::bold('A') . TµAnsi::faint('B') . TµAnsi::italic('C') .
                                        TµAnsi::underline('D') . TµAnsi::blink('E') . TµAnsi::negative('F') .
                                        TµAnsi::strikeout('G') . TµAnsi::resetStyle()), 'ABCDEFG');
check("Ansi colors", TµText::ansiToText(TµAnsi::color('red', 'A') . TµAnsi::backColor('blue', 'white', 'B')), 'AB');
check("Ansi hyperlink (text kept)", TµText::ansiToText(TµAnsi::link('https://temma.net', 'Temma')), 'Temma');
check("cursor and screen sequences", TµText::ansiToText("\e[2K\rA\e[3A\e[?25l\e[H\e[J\e7B\e8\ecC\e[6n"), "\rABC");
check("charset designation (tput sgr0)", TµText::ansiToText("\e[1mA\e(B\e[mB"), 'AB');
check("OSC terminated by BEL", TµText::ansiToText("\e]0;title\x07A"), 'A');
check("truncated sequence at the end", TµText::ansiToText("A\e[3"), 'A');
check("lone escape character at the end", TµText::ansiToText("A\e"), 'A');
check("UTF-8 text is preserved", TµText::ansiToText("\e[31mÉté ✓\e[0m"), 'Été ✓');

/* ********** ansiToHtml() ********** */
print(TµAnsi::bold("ansiToHtml()\n"));
check("null and empty string", [TµText::ansiToHtml(null), TµText::ansiToHtml('')], ['', '']);
check("HTML escaping", TµText::ansiToHtml("<b>\"a\" & 'b'</b>"), '&lt;b&gt;&quot;a&quot; &amp; &#039;b&#039;&lt;/b&gt;');
check("bold", TµText::ansiToHtml(TµAnsi::bold('A') . 'B'), '<span style="font-weight:bold">A</span>B');
check("dim", TµText::ansiToHtml(TµAnsi::faint('A')), '<span style="opacity:.6">A</span>');
check("italic", TµText::ansiToHtml(TµAnsi::italic('A')), '<span style="font-style:italic">A</span>');
check("underline + strike combined", TµText::ansiToHtml("\e[4;9mA\e[24mB\e[0m"),
      '<span style="text-decoration:underline line-through">A</span><span style="text-decoration:line-through">B</span>');
check("blink is ignored", TµText::ansiToHtml(TµAnsi::blink('A')), 'A');
check("hidden", TµText::ansiToHtml("\e[8mA\e[28mB"), '<span style="visibility:hidden">A</span>B');
check("basic colors (30-37, 40-47)", TµText::ansiToHtml("\e[31;42mA\e[0m"), '<span style="color:#c00;background-color:#080">A</span>');
check("bright colors (90-97, 100-107)", TµText::ansiToHtml("\e[91;107mA"), '<span style="color:#f55;background-color:#fff">A</span>');
check("256 colors: base color (Ansi::color('red'))", TµText::ansiToHtml(TµAnsi::color('red', 'A')), '<span style="color:#c00">A</span>');
check("256 colors: color cube", TµText::ansiToHtml("\e[38;5;196mA\e[48;5;21mB"),
      '<span style="color:#ff0000">A</span><span style="color:#ff0000;background-color:#0000ff">B</span>');
check("256 colors: grayscale", TµText::ansiToHtml("\e[38;5;244mA"), '<span style="color:#808080">A</span>');
check("256 colors: invalid index ignored", TµText::ansiToHtml("\e[38;5;300;1mA"), '<span style="font-weight:bold">A</span>');
check("24-bit colors", TµText::ansiToHtml("\e[38;2;255;128;0mA"), '<span style="color:#ff8000">A</span>');
check("colon form (38:5:N, 38:2::R:G:B)", TµText::ansiToHtml("\e[38:5:196mA\e[38:2::0:128:255mB"),
      '<span style="color:#ff0000">A</span><span style="color:#0080ff">B</span>');
check("default colors (39, 49)", TµText::ansiToHtml("\e[31;44mA\e[39mB\e[49mC"),
      '<span style="color:#c00;background-color:#00c">A</span><span style="background-color:#00c">B</span>C');
check("Ansi::backColor() with text color", TµText::ansiToHtml(TµAnsi::backColor('blue', 'white', 'A')),
      '<span style="color:#fff;background-color:#00c">A</span>');
check("reverse without color", TµText::ansiToHtml(TµAnsi::negative('A')), '<span style="color:#fff;background-color:#000">A</span>');
check("reverse with colors", TµText::ansiToHtml("\e[31;7mA\e[27mB"),
      '<span style="color:#fff;background-color:#c00">A</span><span style="color:#c00">B</span>');
check("22 resets bold and dim", TµText::ansiToHtml("\e[1;2mA\e[22mB"), '<span style="font-weight:bold;opacity:.6">A</span>B');
check("empty reset (\\e[m)", TµText::ansiToHtml("\e[1mA\e[mB"), '<span style="font-weight:bold">A</span>B');
check("no empty span for consecutive sequences", TµText::ansiToHtml("\e[1m\e[0m\e[31m\e[32mA\e[0m"), '<span style="color:#080">A</span>');
check("tput output (with \\e(B)", TµText::ansiToHtml("\e[1m\e[31mA\e(B\e[mB"), '<span style="color:#c00;font-weight:bold">A</span>B');
check("other sequences removed", TµText::ansiToHtml("\e[2KA\e[1AB\e]0;title\x07C"), 'ABC');
check("hyperlink", TµText::ansiToHtml(TµAnsi::link('https://temma.net/?a=1&b=2', 'Temma')),
      '<a href="https://temma.net/?a=1&amp;b=2">Temma</a>');
check("styled hyperlink", TµText::ansiToHtml("\e[1m" . TµAnsi::link('mailto:x@y.z', 'X') . "Y\e[0mZ"),
      '<a href="mailto:x@y.z"><span style="font-weight:bold">X</span></a><span style="font-weight:bold">Y</span>Z');
check("style change inside a hyperlink", TµText::ansiToHtml("\e]8;;http://a\e\\A\e[1mB\e]8;;\e\\C"),
      '<a href="http://a">A<span style="font-weight:bold">B</span></a><span style="font-weight:bold">C</span>');
check("unsafe hyperlink (javascript:) not converted", TµText::ansiToHtml(TµAnsi::link('javascript:alert(1)', 'X')), 'X');
check("hyperlink with quotes in URL", TµText::ansiToHtml("\e]8;;https://a/\"><script>\e\\X\e]8;;\e\\"),
      '<a href="https://a/&quot;&gt;&lt;script&gt;">X</a>');
check("unclosed hyperlink and style are closed", TµText::ansiToHtml("\e[1m\e]8;;https://a\e\\X"),
      '<a href="https://a"><span style="font-weight:bold">X</span></a>');
check("line breaks kept", TµText::ansiToHtml("\e[31mA\nB\e[0m\n"), "<span style=\"color:#c00\">A\nB</span>\n");

/* ********** RESULT ********** */
print("\n" . ($failed ? TµAnsi::color('red', "$failed/$count test(s) failed") : TµAnsi::color('green', "All $count tests passed")) . "\n");
exit($failed ? 1 : 0);
